module ietf-interfaces {
  namespace "urn:ietf:params:xml:ns:yang:ietf-interfaces";
  prefix if;

  organization
    "IETF NETMOD (Network Modeling) Working Group";
  contact
    "WG Web:   <https://datatracker.ietf.org/wg/netmod/>
     WG List:  <mailto:netmod@ietf.org>

     Editor:   Martin Bjorklund
               <mailto:mbj@tail-f.com>";
  description
    "This module contains a collection of YANG definitions for
     managing network interfaces.

     Copyright (c) 2018 IETF Trust and the persons identified as
     authors of the code.  All rights reserved.

     Redistribution and use in source and binary forms, with or
     without modification, is permitted pursuant to, and subject
     to the license terms contained in, the Simplified BSD License
     set forth in Section 4.c of the IETF Trust's Legal Provisions
     Relating to IETF Documents
     (https://trustee.ietf.org/license-info).

     This version of this YANG module is part of RFC 8343; see
     the RFC itself for full legal notices.";

  revision 2018-02-20;

  identity interface-type {
    description
      "Base identity from which specific interface types are
       derived.";
  }

  container interfaces {
    config true;
    status current;
    description
      "Interface parameters.";
    list interface {
      key "name";
      config true;
      min-elements 0;
      max-elements 4294967295;
      ordered-by system;
      status current;
      description
        "The list of interfaces on the device.

         The status of an interface is available in this list in the
         operational state.  If the configuration of a
         system-controlled interface cannot be used by the system
         (e.g., the interface hardware present does not match the
         interface type), then the configuration is not applied to
         the system-controlled interface shown in the operational
         state.  If the configuration of a user-controlled interface
         cannot be used by the system, the configured interface is
         not instantiated in the operational state.

         System-controlled interfaces created by the system are
         always present in this list in the operational state,
         whether or not they are configured.";
      leaf name {
        type string;
        config true;
        status current;
        description
          "The name of the interface.

           A device MAY restrict the allowed values for this leaf,
           possibly depending on the type of the interface.
           For system-controlled interfaces, this leaf is the
           device-specific name of the interface.

           If a client tries to create configuration for a
           system-controlled interface that is not present in the
           operational state, the server MAY reject the request if
           the implementation does not support pre-provisioning of
           interfaces or if the name refers to an interface that can
           never exist in the system.  A Network Configuration
           Protocol (NETCONF) server MUST reply with an rpc-error
           with the error-tag 'invalid-value' in this case.

           If the device supports pre-provisioning of interface
           configuration, the 'pre-provisioning' feature is
           advertised.

           If the device allows arbitrarily named user-controlled
           interfaces, the 'arbitrary-names' feature is advertised.

           When a configured user-controlled interface is created by
           the system, it is instantiated with the same name in the
           operational state.

           A server implementation MAY map this leaf to the ifName
           MIB object.  Such an implementation needs to use some
           mechanism to handle the differences in size and characters
           allowed between this leaf and ifName.  The definition of
           such a mechanism is outside the scope of this document.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifName";
      }
      leaf description {
        type string;
        config true;
        status current;
        description
          "A textual description of the interface.

           A server implementation MAY map this leaf to the ifAlias
           MIB object.  Such an implementation needs to use some
           mechanism to handle the differences in size and characters
           allowed between this leaf and ifAlias.  The definition of
           such a mechanism is outside the scope of this document.

           Since ifAlias is defined to be stored in non-volatile
           storage, the MIB implementation MUST map ifAlias to the
           value of 'description' in the persistently stored
           configuration.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifAlias";
      }
      leaf type {
        type identityref {
          base interface-type;
        }
        config true;
        mandatory true;
        status current;
        description
          "The type of the interface.

           When an interface entry is created, a server MAY
           initialize the type leaf with a valid value, e.g., if it
           is possible to derive the type from the name of the
           interface.

           If a client tries to set the type of an interface to a
           value that can never be used by the system, e.g., if the
           type is not supported or if the type does not match the
           name of the interface, the server MUST reject the request.
           A NETCONF server MUST reply with an rpc-error with the
           error-tag 'invalid-value' in this case.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifType";
      }
      leaf enabled {
        type boolean;
        default "true";
        config true;
        status current;
        description
          "This leaf contains the configured, desired state of the
           interface.

           Systems that implement the IF-MIB use the value of this
           leaf in the intended configuration to set
           IF-MIB.ifAdminStatus to 'up' or 'down' after an ifEntry
           has been initialized, as described in RFC 2863.

           Changes in this leaf in the intended configuration are
           reflected in ifAdminStatus.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifAdminStatus";
      }
      leaf oper-status {
        type enumeration {
          enum "up" {
            value 1;
            status current;
            description
              "Ready to pass packets.";
          }
          enum "down" {
            value 2;
            status current;
            description
              "The interface does not pass any packets.";
          }
          enum "testing" {
            value 3;
            status current;
            description
              "In some test mode.  No operational packets can
               be passed.";
          }
          enum "unknown" {
            value 4;
            status current;
            description
              "Status cannot be determined for some reason.";
          }
          enum "dormant" {
            value 5;
            status current;
            description
              "Waiting for some external event.";
          }
          enum "not-present" {
            value 6;
            status current;
            description
              "Some component (typically hardware) is missing.";
          }
          enum "lower-layer-down" {
            value 7;
            status current;
            description
              "Down due to state of lower-layer interface(s).";
          }
        }
        config false;
        mandatory true;
        status current;
        description
          "The current operational state of the interface.

           This leaf has the same semantics as ifOperStatus.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifOperStatus";
      }
      leaf last-change {
        type string {
          pattern "[0-9]{4}-(1[0-2]|0[1-9])-(0[1-9]|[1-2][0-9]|3[0-1])T(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[\\+\\-]((1[0-3]|0[0-9]):([0-5][0-9])|14:00))?";
        }
        config false;
        status current;
        description
          "The time the interface entered its current operational
           state.  If the current state was entered prior to the
           last re-initialization of the local network management
           subsystem, then this node is not present.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifLastChange";
      }
      leaf phys-address {
        type string {
          pattern "([0-9a-fA-F]{2}(:[0-9a-fA-F]{2})*)?";
        }
        config false;
        status current;
        description
          "The interface's address at its protocol sub-layer.  For
           example, for an 802.x interface, this object normally
           contains a Media Access Control (MAC) address.  The
           interface's media-specific modules must define the bit
           and byte ordering and the format of the value of this
           object.  For interfaces that do not have such an address
           (e.g., a serial line), this node is not present.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifPhysAddress";
      }
      leaf-list higher-layer-if {
        type leafref {
          path "/if:interfaces/if:interface/if:name";
          require-instance true;
          type string;
        }
        config false;
        min-elements 0;
        max-elements 4294967295;
        ordered-by user;
        status current;
        description
          "A list of references to interfaces layered on top of this
           interface.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifStackTable";
      }
      leaf-list lower-layer-if {
        type leafref {
          path "/if:interfaces/if:interface/if:name";
          require-instance true;
          type string;
        }
        config false;
        min-elements 0;
        max-elements 4294967295;
        ordered-by user;
        status current;
        description
          "A list of references to interfaces layered underneath this
           interface.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifStackTable";
      }
      leaf speed {
        type uint64;
        units "bits/second";
        config false;
        status current;
        description
          "An estimate of the interface's current bandwidth in bits
           per second.  For interfaces that do not vary in
           bandwidth or for those where no accurate estimation can
           be made, this node should contain the nominal bandwidth.
           For interfaces that have no concept of bandwidth, this
           node is not present.";
        reference
          "RFC 2863: The Interfaces Group MIB -
                     ifSpeed, ifHighSpeed";
      }
      container statistics {
        config false;
        status current;
        description
          "A collection of interface-related statistics objects.";
        leaf discontinuity-time {
          type string {
            pattern "[0-9]{4}-(1[0-2]|0[1-9])-(0[1-9]|[1-2][0-9]|3[0-1])T(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[\\+\\-]((1[0-3]|0[0-9]):([0-5][0-9])|14:00))?";
          }
          config false;
          mandatory true;
          status current;
          description
            "The time on the most recent occasion at which any one or
             more of this interface's counters suffered a
             discontinuity.  If no such discontinuities have occurred
             since the last re-initialization of the local management
             subsystem, then this node contains the time the local
             management subsystem re-initialized itself.";
        }
        leaf in-octets {
          type uint64;
          config false;
          status current;
          description
            "The total number of octets received on the interface,
             including framing characters.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifHCInOctets";
        }
        leaf in-unicast-pkts {
          type uint64;
          config false;
          status current;
          description
            "The number of packets, delivered by this sub-layer to a
             higher (sub-)layer, that were not addressed to a
             multicast or broadcast address at this sub-layer.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifHCInUcastPkts";
        }
        leaf in-broadcast-pkts {
          type uint64;
          config false;
          status current;
          description
            "The number of packets, delivered by this sub-layer to a
             higher (sub-)layer, that were addressed to a broadcast
             address at this sub-layer.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB -
                       ifHCInBroadcastPkts";
        }
        leaf in-multicast-pkts {
          type uint64;
          config false;
          status current;
          description
            "The number of packets, delivered by this sub-layer to a
             higher (sub-)layer, that were addressed to a multicast
             address at this sub-layer.  For a MAC-layer protocol,
             this includes both Group and Functional addresses.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB -
                       ifHCInMulticastPkts";
        }
        leaf in-discards {
          type uint32;
          config false;
          status current;
          description
            "The number of inbound packets that were chosen to be
             discarded even though no errors had been detected to
             prevent their being deliverable to a higher-layer
             protocol.  One possible reason for discarding such a
             packet could be to free up buffer space.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifInDiscards";
        }
        leaf in-errors {
          type uint32;
          config false;
          status current;
          description
            "For packet-oriented interfaces, the number of inbound
             packets that contained errors preventing them from being
             deliverable to a higher-layer protocol.  For character-
             oriented or fixed-length interfaces, the number of
             inbound transmission units that contained errors
             preventing them from being deliverable to a higher-layer
             protocol.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifInErrors";
        }
        leaf in-unknown-protos {
          type uint32;
          config false;
          status current;
          description
            "For packet-oriented interfaces, the number of packets
             received via the interface that were discarded because
             of an unknown or unsupported protocol.  For
             character-oriented or fixed-length interfaces that
             support protocol multiplexing, the number of
             transmission units received via the interface that were
             discarded because of an unknown or unsupported protocol.
             For any interface that does not support protocol
             multiplexing, this counter is not present.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifInUnknownProtos";
        }
        leaf out-octets {
          type uint64;
          config false;
          status current;
          description
            "The total number of octets transmitted out of the
             interface, including framing characters.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifHCOutOctets";
        }
        leaf out-unicast-pkts {
          type uint64;
          config false;
          status current;
          description
            "The total number of packets that higher-level protocols
             requested be transmitted and that were not addressed
             to a multicast or broadcast address at this sub-layer,
             including those that were discarded or not sent.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifHCOutUcastPkts";
        }
        leaf out-broadcast-pkts {
          type uint64;
          config false;
          status current;
          description
            "The total number of packets that higher-level protocols
             requested be transmitted and that were addressed to a
             broadcast address at this sub-layer, including those
             that were discarded or not sent.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB -
                       ifHCOutBroadcastPkts";
        }
        leaf out-multicast-pkts {
          type uint64;
          config false;
          status current;
          description
            "The total number of packets that higher-level protocols
             requested be transmitted and that were addressed to a
             multicast address at this sub-layer, including those
             that were discarded or not sent.  For a MAC-layer
             protocol, this includes both Group and Functional
             addresses.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB -
                       ifHCOutMulticastPkts";
        }
        leaf out-discards {
          type uint32;
          config false;
          status current;
          description
            "The number of outbound packets that were chosen to be
             discarded even though no errors had been detected to
             prevent their being transmitted.  One possible reason
             for discarding such a packet could be to free up buffer
             space.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifOutDiscards";
        }
        leaf out-errors {
          type uint32;
          config false;
          status current;
          description
            "For packet-oriented interfaces, the number of outbound
             packets that could not be transmitted because of errors.
             For character-oriented or fixed-length interfaces, the
             number of outbound transmission units that could not be
             transmitted because of errors.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifOutErrors";
        }
      }
      container ipv4 {
        presence "true";
        config true;
        status current;
        description
          "Parameters for the IPv4 address family.";
        leaf enabled {
          type boolean;
          default "true";
          config true;
          status current;
          description
            "Controls whether IPv4 is enabled or disabled on this
             interface.  When IPv4 is enabled, this interface is
             connected to an IPv4 stack, and the interface can send
             and receive IPv4 packets.";
        }
        leaf forwarding {
          type boolean;
          default "false";
          config true;
          status current;
          description
            "Controls IPv4 packet forwarding of datagrams received by,
             but not addressed to, this interface.  IPv4 routers
             forward datagrams.  IPv4 hosts do not (except those
             source-routed via the host).";
        }
        leaf mtu {
          type uint16 {
            range "68..65535";
          }
          units "octets";
          config true;
          status current;
          description
            "The size, in octets, of the largest IPv4 packet that the
             interface will send and receive.

             The server may restrict the allowed values for this leaf,
             depending on the interface's type.

             If this leaf is not configured, the operationally used MTU
             depends on the interface's type.";
          reference
            "RFC 791: Internet Protocol";
        }
        list address {
          key "ip";
          config true;
          min-elements 0;
          max-elements 4294967295;
          ordered-by system;
          status current;
          description
            "The list of IPv4 addresses on the interface.";
          leaf ip {
            type string {
              pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
              pattern "[0-9\\.]*";
            }
            config true;
            status current;
            description
              "The IPv4 address on the interface.";
          }
          choice subnet {
            config true;
            mandatory true;
            status current;
            description
              "The subnet can be specified as a prefix length or,
               if the server supports non-contiguous netmasks, as
               a netmask.";
            case prefix-length {
              config true;
              status current;
              leaf prefix-length {
                type uint8 {
                  range "0..32";
                }
                config true;
                status current;
                description
                  "The length of the subnet prefix.";
              }
            }
            case netmask {
              config true;
              status current;
            }
          }
          leaf origin {
            type enumeration {
              enum "other" {
                value 0;
                status current;
                description
                  "None of the following.";
              }
              enum "static" {
                value 1;
                status current;
                description
                  "Indicates that the address has been statically
                   configured -- for example, using the Network Configuration
                   Protocol (NETCONF) or a command line interface.";
              }
              enum "dhcp" {
                value 2;
                status current;
                description
                  "Indicates an address that has been assigned to this
                   system by a DHCP server.";
              }
              enum "link-layer" {
                value 3;
                status current;
                description
                  "Indicates an address created by IPv6 stateless
                   autoconfiguration that embeds a link-layer address in its
                   interface identifier.";
              }
              enum "random" {
                value 4;
                status current;
                description
                  "Indicates an address chosen by the system at
                   random, e.g., an IPv4 address within 169.254/16, a
                   temporary address as described in RFC 4941, or a
                   semantically opaque address as described in RFC 7217.";
                reference
                  "RFC 4941: Privacy Extensions for Stateless Address
                             Autoconfiguration in IPv6
                   RFC 7217: A Method for Generating Semantically Opaque
                             Interface Identifiers with IPv6 Stateless
                             Address Autoconfiguration (SLAAC)";
              }
            }
            config false;
            status current;
            description
              "The origin of this address.";
          }
        }
        list neighbor {
          key "ip";
          config true;
          min-elements 0;
          max-elements 4294967295;
          ordered-by system;
          status current;
          description
            "A list of mappings from IPv4 addresses to
             link-layer addresses.

             Entries in this list in the intended configuration are
             used as static entries in the ARP Cache.

             In the operational state, this list represents the ARP
             Cache.";
          reference
            "RFC 826: An Ethernet Address Resolution Protocol";
          leaf ip {
            type string {
              pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
              pattern "[0-9\\.]*";
            }
            config true;
            status current;
            description
              "The IPv4 address of the neighbor node.";
          }
          leaf link-layer-address {
            type string {
              pattern "([0-9a-fA-F]{2}(:[0-9a-fA-F]{2})*)?";
            }
            config true;
            mandatory true;
            status current;
            description
              "The link-layer address of the neighbor node.";
          }
          leaf origin {
            type enumeration {
              enum "other" {
                value 0;
                status current;
                description
                  "None of the following.";
              }
              enum "static" {
                value 1;
                status current;
                description
                  "Indicates that the mapping has been statically
                   configured -- for example, using NETCONF or a command line
                   interface.";
              }
              enum "dynamic" {
                value 2;
                status current;
                description
                  "Indicates that the mapping has been dynamically resolved
                   using, for example, IPv4 ARP or the IPv6 Neighbor
                   Discovery protocol.";
              }
            }
            config false;
            status current;
            description
              "The origin of this neighbor entry.";
          }
        }
        container vrrp {
          config true;
          status current;
          description
            "Configures VRRP version 2 or 3 for IPv4.";
          list vrrp-instance {
            key "vrid";
            config true;
            min-elements 0;
            max-elements 4294967295;
            ordered-by system;
            status current;
            description
              "Defines a virtual router, identified by a VRID, within the
               IPv4 address space.";
            leaf vrid {
              type uint8 {
                range "1..255";
              }
              config true;
              status current;
              description
                "Virtual Router ID (i.e., VRID).";
            }
            leaf version {
              type identityref {
                base vrrp-version;
              }
              config true;
              mandatory true;
              status current;
              description
                "Version 2 or 3 of VRRP.";
            }
            leaf log-state-change {
              type boolean;
              default "false";
              config true;
              status current;
              description
                "Generates VRRP state change messages each time the
                 VRRP instance changes state (from 'up' to 'down'
                 or 'down' to 'up').";
            }
            container preempt {
              config true;
              status current;
              description
                "Enables a higher-priority VRRP backup router to preempt a
                 lower-priority VRRP master.";
              leaf enabled {
                type boolean;
                default "true";
                config true;
                status current;
                description
                  "'true' if preemption is enabled.";
              }
              leaf hold-time {
                type uint16;
                units "seconds";
                default "0";
                config true;
                status current;
                description
                  "Hold time, in seconds, for which a higher-priority VRRP
                   backup router must wait before preempting a lower-priority
                   VRRP master.";
              }
            }
            leaf priority {
              type uint8 {
                range "1..254";
              }
              default "100";
              config true;
              status current;
              description
                "Configures the VRRP election priority for the backup
                 virtual router.";
            }
            leaf accept-mode {
              when "derived-from-or-self(current()/../version, 'vrrp-v3')" {
                description
                  "Applicable only to version 3.";
              }
              type boolean;
              default "false";
              config true;
              status current;
              description
                "Controls whether a virtual router in master state will
                 accept packets addressed to the address owner's IPvX address
                 as its own if it is not the IPvX address owner.  The default
                 is 'false'.  Deployments that rely on, for example, pinging
                 the address owner's IPvX address may wish to configure
                 accept-mode to 'true'.

                 Note: IPv6 Neighbor Solicitations and Neighbor
                 Advertisements MUST NOT be dropped when accept-mode
                 is 'false'.";
            }
            choice advertise-interval-choice {
              config true;
              status current;
              description
                "The options for the advertisement interval at which VRRPv2
                 or VRRPv3 advertisements are sent from the specified
                 interface.";
              case v2 {
                when "derived-from-or-self(version, 'vrrp-v2')" {
                  description
                    "Applicable only to version 2.";
                }
                config true;
                status current;
                leaf advertise-interval-sec {
                  type uint8 {
                    range "1..254";
                  }
                  units "seconds";
                  default "1";
                  config true;
                  status current;
                  description
                    "Configures the interval that VRRPv2 advertisements
                     are sent from the specified interface.";
                }
              }
              case v3 {
                when "derived-from-or-self(version, 'vrrp-v3')" {
                  description
                    "Applicable only to version 3.";
                }
                config true;
                status current;
                leaf advertise-interval-centi-sec {
                  type uint16 {
                    range "1..4095";
                  }
                  units "centiseconds";
                  default "100";
                  config true;
                  status current;
                  description
                    "Configures the interval that VRRPv3 advertisements
                     are sent from the specified interface.";
                }
              }
            }
            container track {
              config true;
              status current;
              description
                "Enables the specified VRRP instance to track interfaces
                 or networks.";
              container interfaces {
                config true;
                status current;
                description
                  "Enables the specified VRRPv2 or VRRPv3 instance to track
                   interfaces.  Interface tracking prevents traffic loss by
                   detecting the availability of interfaces.  The operational
                   states of other interfaces are associated with the
                   priority of a VRRP router.  When a tracked interface
                   becomes unavailable (or 'operational down'), the priority
                   of the VRRP router decrements.  When an unavailable
                   interface becomes available again, the priority of the
                   VRRP router is incremented by the same amount.";
                list interface {
                  key "interface";
                  config true;
                  min-elements 0;
                  max-elements 4294967295;
                  ordered-by system;
                  status current;
                  description
                    "Interface to track.";
                  leaf interface {
                    type leafref {
                      path "/if:interfaces/if:interface/if:name";
                      require-instance true;
                      type string;
                    }
                    must "/if:interfaces/if:interface[if:name=current()]/ip:ipv4" {
                      description
                        "Interface is IPv4.";
                    }
                    config true;
                    status current;
                    description
                      "Interface to track.";
                  }
                  leaf priority-decrement {
                    type uint8 {
                      range "1..254";
                    }
                    default "10";
                    config true;
                    status current;
                    description
                      "Specifies how much to decrement the priority of the
                       VRRP instance if the interface goes down.";
                  }
                }
              }
              container networks {
                config true;
                status current;
                description
                  "Enables the VRRPv2 or VRRPv3 router instance to track the
                   specified networks through their IPv4 network prefixes.
                   Network tracking prevents traffic loss by detecting
                   network connectivity failure.  The states of
                   connectivity to some networks are associated with the
                   priority of a VRRP router.  When connectivity to a
                   tracked network represented by its prefix is lost, the
                   priority of the VRRP router decrements.  When an
                   unavailable network is again reachable, the priority of
                   the VRRP router is incremented by the same amount.";
                list network {
                  key "prefix";
                  config true;
                  min-elements 0;
                  max-elements 4294967295;
                  ordered-by system;
                  status current;
                  description
                    "Enables the specified VRRPv2 or VRRPv3 instance to
                     track an IPv4 network by specifying the prefix of the
                     IPv4 network.";
                  leaf prefix {
                    type string {
                      pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])/(([0-9])|([1-2][0-9])|(3[0-2]))";
                    }
                    config true;
                    status current;
                    description
                      "The IPv4 prefix of the network to track.";
                  }
                  leaf priority-decrement {
                    type uint8 {
                      range "1..254";
                    }
                    default "10";
                    config true;
                    status current;
                    description
                      "Specifies how much to decrement the priority of the
                       VRRP router if there is a failure in the IPv4
                       network.";
                  }
                }
              }
            }
            container virtual-ipv4-addresses {
              config true;
              status current;
              description
                "Configures the virtual IPv4 address for the
                 VRRP interface.";
              list virtual-ipv4-address {
                key "ipv4-address";
                config true;
                min-elements 0;
                max-elements 16;
                ordered-by system;
                status current;
                description
                  "Virtual IPv4 addresses for a single VRRP instance.  For a
                   VRRP owner router, the virtual address must match one
                   of the IPv4 addresses configured on the interface
                   corresponding to the virtual router.";
                leaf ipv4-address {
                  type string {
                    pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
                  }
                  config true;
                  status current;
                  description
                    "An IPv4 address associated with a virtual router.";
                  reference
                    "RFC 5798: Virtual Router Redundancy Protocol (VRRP)
                               Version 3 for IPv4 and IPv6.  Section 1.2";
                }
              }
            }
            leaf state {
              type identityref {
                base vrrp-state-type;
              }
              config false;
              status current;
              description
                "Operational state.";
            }
            leaf is-owner {
              type boolean;
              config false;
              status current;
              description
                "Set to 'true' if this virtual router is the owner.";
            }
            leaf last-adv-source {
              type union {
                type string {
                  pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
                }
                type string {
                  pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
                  pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
                }
              }
              config false;
              status current;
              description
                "Last advertised IPv4/IPv6 source address.";
            }
            leaf up-datetime {
              type string {
                pattern "[0-9]{4}-(1[0-2]|0[1-9])-(0[1-9]|[1-2][0-9]|3[0-1])T(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[\\+\\-]((1[0-3]|0[0-9]):([0-5][0-9])|14:00))?";
              }
              config false;
              status current;
              description
                "The date and time when this virtual router
                 transitioned out of 'init' state.";
            }
            leaf master-down-interval {
              type uint32;
              units "centiseconds";
              config false;
              status current;
              description
                "Time interval for the backup virtual router to declare
                 'master down'.";
            }
            leaf skew-time {
              type uint32;
              units "microseconds";
              config false;
              status current;
              description
                "Calculated based on the priority and advertisement
                 interval configuration command parameters.  See RFC 3768.";
            }
            leaf last-event {
              type identityref {
                base vrrp-event-type;
              }
              config false;
              status current;
              description
                "Last reported event.";
            }
            leaf new-master-reason {
              type enumeration {
                enum "not-master" {
                  value 0;
                  status current;
                  description
                    "The virtual router has never transitioned to master
                     state.";
                }
                enum "priority" {
                  value 1;
                  status current;
                  description
                    "Priority was higher.";
                }
                enum "preempted" {
                  value 2;
                  status current;
                  description
                    "The master was preempted.";
                }
                enum "no-response" {
                  value 3;
                  status current;
                  description
                    "Previous master did not respond.";
                }
              }
              config false;
              status current;
              description
                "Indicates why the virtual router has transitioned to
                 master state.";
            }
            container statistics {
              config false;
              status current;
              description
                "VRRP statistics.";
              leaf discontinuity-datetime {
                type string {
                  pattern "[0-9]{4}-(1[0-2]|0[1-9])-(0[1-9]|[1-2][0-9]|3[0-1])T(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[\\+\\-]((1[0-3]|0[0-9]):([0-5][0-9])|14:00))?";
                }
                config false;
                status current;
                description
                  "The time on the most recent occasion at which any one or
                   more of the VRRP statistics counters suffered a
                   discontinuity.  If no such discontinuities have occurred
                   since the last re-initialization of the local management
                   subsystem, then this node contains the time that the
                   local management subsystem re-initialized itself.";
              }
              leaf master-transitions {
                type uint32;
                config false;
                status current;
                description
                  "The total number of times that this virtual router's
                   state has transitioned to 'master'.";
              }
              leaf advertisement-rcvd {
                type uint64;
                config false;
                status current;
                description
                  "The total number of VRRP advertisements received by
                   this virtual router.";
              }
              leaf advertisement-sent {
                type uint64;
                config false;
                status current;
                description
                  "The total number of VRRP advertisements sent by
                   this virtual router.";
              }
              leaf priority-zero-pkts-rcvd {
                type uint64;
                config false;
                status current;
                description
                  "The total number of VRRP packets received by the
                   virtual router with a priority of 0.";
              }
              leaf priority-zero-pkts-sent {
                type uint64;
                config false;
                status current;
                description
                  "The total number of VRRP packets sent by the
                   virtual router with a priority of 0.";
              }
              leaf invalid-type-pkts-rcvd {
                type uint64;
                config false;
                status current;
                description
                  "The number of VRRP packets received by the virtual
                   router with an invalid value in the 'type' field.";
              }
              leaf packet-length-errors {
                type uint64;
                config false;
                status current;
                description
                  "The total number of packets received with a packet
                   length less than the length of the VRRP header.";
              }
            }
          }
        }
      }
      container ipv6 {
        presence "true";
        config true;
        status current;
        description
          "Parameters for the IPv6 address family.";
        leaf enabled {
          type boolean;
          default "true";
          config true;
          status current;
          description
            "Controls whether IPv6 is enabled or disabled on this
             interface.  When IPv6 is enabled, this interface is
             connected to an IPv6 stack, and the interface can send
             and receive IPv6 packets.";
        }
        leaf forwarding {
          type boolean;
          default "false";
          config true;
          status current;
          description
            "Controls IPv6 packet forwarding of datagrams received by,
             but not addressed to, this interface.  IPv6 routers
             forward datagrams.  IPv6 hosts do not (except those
             source-routed via the host).";
          reference
            "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                       Section 6.2.1, IsRouter";
        }
        leaf mtu {
          type uint32 {
            range "1280..4294967295";
          }
          units "octets";
          config true;
          status current;
          description
            "The size, in octets, of the largest IPv6 packet that the
             interface will send and receive.

             The server may restrict the allowed values for this leaf,
             depending on the interface's type.

             If this leaf is not configured, the operationally used MTU
             depends on the interface's type.";
          reference
            "RFC 8200: Internet Protocol, Version 6 (IPv6)
                       Specification
                       Section 5";
        }
        list address {
          key "ip";
          config true;
          min-elements 0;
          max-elements 4294967295;
          ordered-by system;
          status current;
          description
            "The list of IPv6 addresses on the interface.";
          leaf ip {
            type string {
              pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
              pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
              pattern "[0-9a-fA-F:\\.]*";
            }
            config true;
            status current;
            description
              "The IPv6 address on the interface.";
          }
          leaf prefix-length {
            type uint8 {
              range "0..128";
            }
            config true;
            mandatory true;
            status current;
            description
              "The length of the subnet prefix.";
          }
          leaf origin {
            type enumeration {
              enum "other" {
                value 0;
                status current;
                description
                  "None of the following.";
              }
              enum "static" {
                value 1;
                status current;
                description
                  "Indicates that the address has been statically
                   configured -- for example, using the Network Configuration
                   Protocol (NETCONF) or a command line interface.";
              }
              enum "dhcp" {
                value 2;
                status current;
                description
                  "Indicates an address that has been assigned to this
                   system by a DHCP server.";
              }
              enum "link-layer" {
                value 3;
                status current;
                description
                  "Indicates an address created by IPv6 stateless
                   autoconfiguration that embeds a link-layer address in its
                   interface identifier.";
              }
              enum "random" {
                value 4;
                status current;
                description
                  "Indicates an address chosen by the system at
                   random, e.g., an IPv4 address within 169.254/16, a
                   temporary address as described in RFC 4941, or a
                   semantically opaque address as described in RFC 7217.";
                reference
                  "RFC 4941: Privacy Extensions for Stateless Address
                             Autoconfiguration in IPv6
                   RFC 7217: A Method for Generating Semantically Opaque
                             Interface Identifiers with IPv6 Stateless
                             Address Autoconfiguration (SLAAC)";
              }
            }
            config false;
            status current;
            description
              "The origin of this address.";
          }
          leaf status {
            type enumeration {
              enum "preferred" {
                value 0;
                status current;
                description
                  "This is a valid address that can appear as the
                   destination or source address of a packet.";
              }
              enum "deprecated" {
                value 1;
                status current;
                description
                  "This is a valid but deprecated address that should
                   no longer be used as a source address in new
                   communications, but packets addressed to such an
                   address are processed as expected.";
              }
              enum "invalid" {
                value 2;
                status current;
                description
                  "This isn't a valid address, and it shouldn't appear
                   as the destination or source address of a packet.";
              }
              enum "inaccessible" {
                value 3;
                status current;
                description
                  "The address is not accessible because the interface
                   to which this address is assigned is not
                   operational.";
              }
              enum "unknown" {
                value 4;
                status current;
                description
                  "The status cannot be determined for some reason.";
              }
              enum "tentative" {
                value 5;
                status current;
                description
                  "The uniqueness of the address on the link is being
                   verified.  Addresses in this state should not be
                   used for general communication and should only be
                   used to determine the uniqueness of the address.";
              }
              enum "duplicate" {
                value 6;
                status current;
                description
                  "The address has been determined to be non-unique on
                   the link and so must not be used.";
              }
              enum "optimistic" {
                value 7;
                status current;
                description
                  "The address is available for use, subject to
                   restrictions, while its uniqueness on a link is
                   being verified.";
              }
            }
            config false;
            status current;
            description
              "The status of an address.  Most of the states correspond
               to states from the IPv6 Stateless Address
               Autoconfiguration protocol.";
            reference
              "RFC 4293: Management Information Base for the
                         Internet Protocol (IP)
                         - IpAddressStatusTC
               RFC 4862: IPv6 Stateless Address Autoconfiguration";
          }
        }
        list neighbor {
          key "ip";
          config true;
          min-elements 0;
          max-elements 4294967295;
          ordered-by system;
          status current;
          description
            "A list of mappings from IPv6 addresses to
             link-layer addresses.

             Entries in this list in the intended configuration are
             used as static entries in the Neighbor Cache.

             In the operational state, this list represents the
             Neighbor Cache.";
          reference
            "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)";
          leaf ip {
            type string {
              pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
              pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
              pattern "[0-9a-fA-F:\\.]*";
            }
            config true;
            status current;
            description
              "The IPv6 address of the neighbor node.";
          }
          leaf link-layer-address {
            type string {
              pattern "([0-9a-fA-F]{2}(:[0-9a-fA-F]{2})*)?";
            }
            config true;
            mandatory true;
            status current;
            description
              "The link-layer address of the neighbor node.

               In the operational state, if the neighbor's 'state' leaf
               is 'incomplete', this leaf is not instantiated.";
          }
          leaf origin {
            type enumeration {
              enum "other" {
                value 0;
                status current;
                description
                  "None of the following.";
              }
              enum "static" {
                value 1;
                status current;
                description
                  "Indicates that the mapping has been statically
                   configured -- for example, using NETCONF or a command line
                   interface.";
              }
              enum "dynamic" {
                value 2;
                status current;
                description
                  "Indicates that the mapping has been dynamically resolved
                   using, for example, IPv4 ARP or the IPv6 Neighbor
                   Discovery protocol.";
              }
            }
            config false;
            status current;
            description
              "The origin of this neighbor entry.";
          }
          leaf is-router {
            type empty;
            config false;
            status current;
            description
              "Indicates that the neighbor node acts as a router.";
          }
          leaf state {
            type enumeration {
              enum "incomplete" {
                value 0;
                status current;
                description
                  "Address resolution is in progress, and the
                   link-layer address of the neighbor has not yet been
                   determined.";
              }
              enum "reachable" {
                value 1;
                status current;
                description
                  "Roughly speaking, the neighbor is known to have been
                   reachable recently (within tens of seconds ago).";
              }
              enum "stale" {
                value 2;
                status current;
                description
                  "The neighbor is no longer known to be reachable, but
                   until traffic is sent to the neighbor no attempt
                   should be made to verify its reachability.";
              }
              enum "delay" {
                value 3;
                status current;
                description
                  "The neighbor is no longer known to be reachable, and
                   traffic has recently been sent to the neighbor.
                   Rather than probe the neighbor immediately, however,
                   delay sending probes for a short while in order to
                   give upper-layer protocols a chance to provide
                   reachability confirmation.";
              }
              enum "probe" {
                value 4;
                status current;
                description
                  "The neighbor is no longer known to be reachable, and
                   unicast Neighbor Solicitation probes are being sent
                   to verify reachability.";
              }
            }
            config false;
            status current;
            description
              "The Neighbor Unreachability Detection state of this
               entry.";
            reference
              "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                         Section 7.3.2";
          }
        }
        leaf dup-addr-detect-transmits {
          type uint32;
          default "1";
          config true;
          status current;
          description
            "The number of consecutive Neighbor Solicitation messages
             sent while performing Duplicate Address Detection on a
             tentative address.  A value of zero indicates that
             Duplicate Address Detection is not performed on
             tentative addresses.  A value of one indicates a single
             transmission with no follow-up retransmissions.";
          reference
            "RFC 4862: IPv6 Stateless Address Autoconfiguration";
        }
        container autoconf {
          config true;
          status current;
          description
            "Parameters to control the autoconfiguration of IPv6
             addresses, as described in RFC 4862.";
          reference
            "RFC 4862: IPv6 Stateless Address Autoconfiguration";
          leaf create-global-addresses {
            type boolean;
            default "true";
            config true;
            status current;
            description
              "If enabled, the host creates global addresses as
               described in RFC 4862.";
            reference
              "RFC 4862: IPv6 Stateless Address Autoconfiguration
                         Section 5.5";
          }
        }
        container vrrp {
          config true;
          status current;
          description
            "Configures VRRP version 3 for IPv6.";
          list vrrp-instance {
            must "derived-from-or-self(version, 'vrrp-v3')" {
              description
                "IPv6 is only supported by version 3.";
            }
            key ", vrid";
            config true;
            min-elements 0;
            max-elements 4294967295;
            ordered-by system;
            status current;
            description
              "Defines a virtual router, identified by a VRID, within the
               IPv6 address space.";
            leaf vrid {
              type uint8 {
                range "1..255";
              }
              config true;
              status current;
              description
                "Virtual Router ID (i.e., VRID).";
            }
            leaf version {
              type identityref {
                base vrrp-version;
              }
              config true;
              mandatory true;
              status current;
              description
                "Version 2 or 3 of VRRP.";
            }
            leaf log-state-change {
              type boolean;
              default "false";
              config true;
              status current;
              description
                "Generates VRRP state change messages each time the
                 VRRP instance changes state (from 'up' to 'down'
                 or 'down' to 'up').";
            }
            container preempt {
              config true;
              status current;
              description
                "Enables a higher-priority VRRP backup router to preempt a
                 lower-priority VRRP master.";
              leaf enabled {
                type boolean;
                default "true";
                config true;
                status current;
                description
                  "'true' if preemption is enabled.";
              }
              leaf hold-time {
                type uint16;
                units "seconds";
                default "0";
                config true;
                status current;
                description
                  "Hold time, in seconds, for which a higher-priority VRRP
                   backup router must wait before preempting a lower-priority
                   VRRP master.";
              }
            }
            leaf priority {
              type uint8 {
                range "1..254";
              }
              default "100";
              config true;
              status current;
              description
                "Configures the VRRP election priority for the backup
                 virtual router.";
            }
            leaf accept-mode {
              when "derived-from-or-self(current()/../version, 'vrrp-v3')" {
                description
                  "Applicable only to version 3.";
              }
              type boolean;
              default "false";
              config true;
              status current;
              description
                "Controls whether a virtual router in master state will
                 accept packets addressed to the address owner's IPvX address
                 as its own if it is not the IPvX address owner.  The default
                 is 'false'.  Deployments that rely on, for example, pinging
                 the address owner's IPvX address may wish to configure
                 accept-mode to 'true'.

                 Note: IPv6 Neighbor Solicitations and Neighbor
                 Advertisements MUST NOT be dropped when accept-mode
                 is 'false'.";
            }
            leaf advertise-interval-centi-sec {
              type uint16 {
                range "1..4095";
              }
              units "centiseconds";
              default "100";
              config true;
              status current;
              description
                "Configures the interval that VRRPv3 advertisements
                 are sent from the specified interface.";
            }
            container track {
              config true;
              status current;
              description
                "Enables the specified VRRP instance to track interfaces
                 or networks.";
              container interfaces {
                config true;
                status current;
                description
                  "Enables the specified VRRPv2 or VRRPv3 instance to track
                   interfaces.  Interface tracking prevents traffic loss by
                   detecting the availability of interfaces.  The operational
                   states of other interfaces are associated with the
                   priority of a VRRP router.  When a tracked interface
                   becomes unavailable (or 'operational down'), the priority
                   of the VRRP router decrements.  When an unavailable
                   interface becomes available again, the priority of the
                   VRRP router is incremented by the same amount.";
                list interface {
                  key "interface";
                  config true;
                  min-elements 0;
                  max-elements 4294967295;
                  ordered-by system;
                  status current;
                  description
                    "Interface to track.";
                  leaf interface {
                    type leafref {
                      path "/if:interfaces/if:interface/if:name";
                      require-instance true;
                      type string;
                    }
                    must "/if:interfaces/if:interface[if:name=current()]/ip:ipv6" {
                      description
                        "Interface is IPv6.";
                    }
                    config true;
                    status current;
                    description
                      "Interface to track.";
                  }
                  leaf priority-decrement {
                    type uint8 {
                      range "1..254";
                    }
                    default "10";
                    config true;
                    status current;
                    description
                      "Specifies how much to decrement the priority of the
                       VRRP instance if the interface goes down.";
                  }
                }
              }
              container networks {
                config true;
                status current;
                description
                  "Enables the VRRPv2 or VRRPv3 router instance to track the
                   specified networks through their IPv6 network prefixes.
                   Network tracking prevents traffic loss by detecting
                   network connectivity failure.  The states of
                   connectivity to some networks are associated with the
                   priority of a VRRP router.  When connectivity to a
                   tracked network represented by its prefix is lost, the
                   priority of the VRRP router decrements.  When an
                   unavailable network is again reachable, the priority of
                   the VRRP router is incremented by the same amount.";
                list network {
                  key "prefix";
                  config true;
                  min-elements 0;
                  max-elements 4294967295;
                  ordered-by system;
                  status current;
                  description
                    "Enables the specified VRRPv2 or VRRPv3 instance to
                     track an IPv6 network by specifying the prefix of the
                     IPv6 network.";
                  leaf prefix {
                    type string {
                      pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(/(([0-9])|([0-9]{2})|(1[0-1][0-9])|(12[0-8])))";
                      pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(/.+)";
                    }
                    config true;
                    status current;
                    description
                      "The IPv6 prefix of the network to track.";
                  }
                  leaf priority-decrement {
                    type uint8 {
                      range "1..254";
                    }
                    default "10";
                    config true;
                    status current;
                    description
                      "Specifies how much to decrement the priority of the
                       VRRP router if there is a failure in the IPv6
                       network.";
                  }
                }
              }
            }
            container virtual-ipv6-addresses {
              config true;
              status current;
              description
                "Configures the virtual IPv6 address for the
                 VRRP interface.";
              list virtual-ipv6-address {
                key "ipv6-address";
                config true;
                min-elements 0;
                max-elements 2;
                ordered-by system;
                status current;
                description
                  "Two IPv6 addresses are allowed.  The first address must
                   be a link-local address.  The second address can be a
                   link-local or global address.";
                leaf ipv6-address {
                  type string {
                    pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
                    pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
                  }
                  config true;
                  status current;
                  description
                    "An IPv6 address associated with a virtual router.";
                  reference
                    "RFC 5798: Virtual Router Redundancy Protocol (VRRP)
                               Version 3 for IPv4 and IPv6.  Section 1.3";
                }
              }
            }
            leaf state {
              type identityref {
                base vrrp-state-type;
              }
              config false;
              status current;
              description
                "Operational state.";
            }
            leaf is-owner {
              type boolean;
              config false;
              status current;
              description
                "Set to 'true' if this virtual router is the owner.";
            }
            leaf last-adv-source {
              type union {
                type string {
                  pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
                }
                type string {
                  pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
                  pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
                }
              }
              config false;
              status current;
              description
                "Last advertised IPv4/IPv6 source address.";
            }
            leaf up-datetime {
              type string {
                pattern "[0-9]{4}-(1[0-2]|0[1-9])-(0[1-9]|[1-2][0-9]|3[0-1])T(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[\\+\\-]((1[0-3]|0[0-9]):([0-5][0-9])|14:00))?";
              }
              config false;
              status current;
              description
                "The date and time when this virtual router
                 transitioned out of 'init' state.";
            }
            leaf master-down-interval {
              type uint32;
              units "centiseconds";
              config false;
              status current;
              description
                "Time interval for the backup virtual router to declare
                 'master down'.";
            }
            leaf skew-time {
              type uint32;
              units "microseconds";
              config false;
              status current;
              description
                "Calculated based on the priority and advertisement
                 interval configuration command parameters.  See RFC 3768.";
            }
            leaf last-event {
              type identityref {
                base vrrp-event-type;
              }
              config false;
              status current;
              description
                "Last reported event.";
            }
            leaf new-master-reason {
              type enumeration {
                enum "not-master" {
                  value 0;
                  status current;
                  description
                    "The virtual router has never transitioned to master
                     state.";
                }
                enum "priority" {
                  value 1;
                  status current;
                  description
                    "Priority was higher.";
                }
                enum "preempted" {
                  value 2;
                  status current;
                  description
                    "The master was preempted.";
                }
                enum "no-response" {
                  value 3;
                  status current;
                  description
                    "Previous master did not respond.";
                }
              }
              config false;
              status current;
              description
                "Indicates why the virtual router has transitioned to
                 master state.";
            }
            container statistics {
              config false;
              status current;
              description
                "VRRP statistics.";
              leaf discontinuity-datetime {
                type string {
                  pattern "[0-9]{4}-(1[0-2]|0[1-9])-(0[1-9]|[1-2][0-9]|3[0-1])T(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[\\+\\-]((1[0-3]|0[0-9]):([0-5][0-9])|14:00))?";
                }
                config false;
                status current;
                description
                  "The time on the most recent occasion at which any one or
                   more of the VRRP statistics counters suffered a
                   discontinuity.  If no such discontinuities have occurred
                   since the last re-initialization of the local management
                   subsystem, then this node contains the time that the
                   local management subsystem re-initialized itself.";
              }
              leaf master-transitions {
                type uint32;
                config false;
                status current;
                description
                  "The total number of times that this virtual router's
                   state has transitioned to 'master'.";
              }
              leaf advertisement-rcvd {
                type uint64;
                config false;
                status current;
                description
                  "The total number of VRRP advertisements received by
                   this virtual router.";
              }
              leaf advertisement-sent {
                type uint64;
                config false;
                status current;
                description
                  "The total number of VRRP advertisements sent by
                   this virtual router.";
              }
              leaf priority-zero-pkts-rcvd {
                type uint64;
                config false;
                status current;
                description
                  "The total number of VRRP packets received by the
                   virtual router with a priority of 0.";
              }
              leaf priority-zero-pkts-sent {
                type uint64;
                config false;
                status current;
                description
                  "The total number of VRRP packets sent by the
                   virtual router with a priority of 0.";
              }
              leaf invalid-type-pkts-rcvd {
                type uint64;
                config false;
                status current;
                description
                  "The number of VRRP packets received by the virtual
                   router with an invalid value in the 'type' field.";
              }
              leaf packet-length-errors {
                type uint64;
                config false;
                status current;
                description
                  "The total number of packets received with a packet
                   length less than the length of the VRRP header.";
              }
            }
          }
        }
      }
    }
  }
  container interfaces-state {
    config false;
    status deprecated;
    description
      "Data nodes for the operational state of interfaces.";
    list interface {
      key "name";
      config false;
      min-elements 0;
      max-elements 4294967295;
      ordered-by user;
      status deprecated;
      description
        "The list of interfaces on the device.

         System-controlled interfaces created by the system are
         always present in this list, whether or not they are
         configured.";
      leaf name {
        type string;
        config false;
        status deprecated;
        description
          "The name of the interface.

           A server implementation MAY map this leaf to the ifName
           MIB object.  Such an implementation needs to use some
           mechanism to handle the differences in size and characters
           allowed between this leaf and ifName.  The definition of
           such a mechanism is outside the scope of this document.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifName";
      }
      leaf type {
        type identityref {
          base interface-type;
        }
        config false;
        mandatory true;
        status deprecated;
        description
          "The type of the interface.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifType";
      }
      leaf oper-status {
        type enumeration {
          enum "up" {
            value 1;
            status current;
            description
              "Ready to pass packets.";
          }
          enum "down" {
            value 2;
            status current;
            description
              "The interface does not pass any packets.";
          }
          enum "testing" {
            value 3;
            status current;
            description
              "In some test mode.  No operational packets can
               be passed.";
          }
          enum "unknown" {
            value 4;
            status current;
            description
              "Status cannot be determined for some reason.";
          }
          enum "dormant" {
            value 5;
            status current;
            description
              "Waiting for some external event.";
          }
          enum "not-present" {
            value 6;
            status current;
            description
              "Some component (typically hardware) is missing.";
          }
          enum "lower-layer-down" {
            value 7;
            status current;
            description
              "Down due to state of lower-layer interface(s).";
          }
        }
        config false;
        mandatory true;
        status deprecated;
        description
          "The current operational state of the interface.

           This leaf has the same semantics as ifOperStatus.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifOperStatus";
      }
      leaf last-change {
        type string {
          pattern "[0-9]{4}-(1[0-2]|0[1-9])-(0[1-9]|[1-2][0-9]|3[0-1])T(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[\\+\\-]((1[0-3]|0[0-9]):([0-5][0-9])|14:00))?";
        }
        config false;
        status deprecated;
        description
          "The time the interface entered its current operational
           state.  If the current state was entered prior to the
           last re-initialization of the local network management
           subsystem, then this node is not present.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifLastChange";
      }
      leaf phys-address {
        type string {
          pattern "([0-9a-fA-F]{2}(:[0-9a-fA-F]{2})*)?";
        }
        config false;
        status deprecated;
        description
          "The interface's address at its protocol sub-layer.  For
           example, for an 802.x interface, this object normally
           contains a Media Access Control (MAC) address.  The
           interface's media-specific modules must define the bit
           and byte ordering and the format of the value of this
           object.  For interfaces that do not have such an address
           (e.g., a serial line), this node is not present.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifPhysAddress";
      }
      leaf-list higher-layer-if {
        type leafref {
          path "/if:interfaces-state/if:interface/if:name";
          require-instance true;
          type string;
        }
        config false;
        min-elements 0;
        max-elements 4294967295;
        ordered-by user;
        status deprecated;
        description
          "A list of references to interfaces layered on top of this
           interface.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifStackTable";
      }
      leaf-list lower-layer-if {
        type leafref {
          path "/if:interfaces-state/if:interface/if:name";
          require-instance true;
          type string;
        }
        config false;
        min-elements 0;
        max-elements 4294967295;
        ordered-by user;
        status deprecated;
        description
          "A list of references to interfaces layered underneath this
           interface.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifStackTable";
      }
      leaf speed {
        type uint64;
        units "bits/second";
        config false;
        status deprecated;
        description
          "An estimate of the interface's current bandwidth in bits
           per second.  For interfaces that do not vary in
           bandwidth or for those where no accurate estimation can

           be made, this node should contain the nominal bandwidth.
           For interfaces that have no concept of bandwidth, this
           node is not present.";
        reference
          "RFC 2863: The Interfaces Group MIB -
                     ifSpeed, ifHighSpeed";
      }
      container statistics {
        config false;
        status deprecated;
        description
          "A collection of interface-related statistics objects.";
        leaf discontinuity-time {
          type string {
            pattern "[0-9]{4}-(1[0-2]|0[1-9])-(0[1-9]|[1-2][0-9]|3[0-1])T(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[\\+\\-]((1[0-3]|0[0-9]):([0-5][0-9])|14:00))?";
          }
          config false;
          mandatory true;
          status deprecated;
          description
            "The time on the most recent occasion at which any one or
             more of this interface's counters suffered a
             discontinuity.  If no such discontinuities have occurred
             since the last re-initialization of the local management
             subsystem, then this node contains the time the local
             management subsystem re-initialized itself.";
        }
        leaf in-octets {
          type uint64;
          config false;
          status deprecated;
          description
            "The total number of octets received on the interface,
             including framing characters.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifHCInOctets";
        }
        leaf in-unicast-pkts {
          type uint64;
          config false;
          status deprecated;
          description
            "The number of packets, delivered by this sub-layer to a
             higher (sub-)layer, that were not addressed to a
             multicast or broadcast address at this sub-layer.
             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifHCInUcastPkts";
        }
        leaf in-broadcast-pkts {
          type uint64;
          config false;
          status deprecated;
          description
            "The number of packets, delivered by this sub-layer to a
             higher (sub-)layer, that were addressed to a broadcast
             address at this sub-layer.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB -
                       ifHCInBroadcastPkts";
        }
        leaf in-multicast-pkts {
          type uint64;
          config false;
          status deprecated;
          description
            "The number of packets, delivered by this sub-layer to a
             higher (sub-)layer, that were addressed to a multicast
             address at this sub-layer.  For a MAC-layer protocol,
             this includes both Group and Functional addresses.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB -
                       ifHCInMulticastPkts";
        }
        leaf in-discards {
          type uint32;
          config false;
          status deprecated;
          description
            "The number of inbound packets that were chosen to be
             discarded even though no errors had been detected to
             prevent their being deliverable to a higher-layer
             protocol.  One possible reason for discarding such a
             packet could be to free up buffer space.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifInDiscards";
        }
        leaf in-errors {
          type uint32;
          config false;
          status deprecated;
          description
            "For packet-oriented interfaces, the number of inbound
             packets that contained errors preventing them from being
             deliverable to a higher-layer protocol.  For character-
             oriented or fixed-length interfaces, the number of
             inbound transmission units that contained errors
             preventing them from being deliverable to a higher-layer
             protocol.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifInErrors";
        }
        leaf in-unknown-protos {
          type uint32;
          config false;
          status deprecated;
          description
            "For packet-oriented interfaces, the number of packets
             received via the interface that were discarded because
             of an unknown or unsupported protocol.  For
             character-oriented or fixed-length interfaces that
             support protocol multiplexing, the number of
             transmission units received via the interface that were
             discarded because of an unknown or unsupported protocol.
             For any interface that does not support protocol
             multiplexing, this counter is not present.
             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifInUnknownProtos";
        }
        leaf out-octets {
          type uint64;
          config false;
          status deprecated;
          description
            "The total number of octets transmitted out of the
             interface, including framing characters.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifHCOutOctets";
        }
        leaf out-unicast-pkts {
          type uint64;
          config false;
          status deprecated;
          description
            "The total number of packets that higher-level protocols
             requested be transmitted and that were not addressed
             to a multicast or broadcast address at this sub-layer,
             including those that were discarded or not sent.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifHCOutUcastPkts";
        }
        leaf out-broadcast-pkts {
          type uint64;
          config false;
          status deprecated;
          description
            "The total number of packets that higher-level protocols
             requested be transmitted and that were addressed to a
             broadcast address at this sub-layer, including those
             that were discarded or not sent.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB -
                       ifHCOutBroadcastPkts";
        }
        leaf out-multicast-pkts {
          type uint64;
          config false;
          status deprecated;
          description
            "The total number of packets that higher-level protocols
             requested be transmitted and that were addressed to a
             multicast address at this sub-layer, including those
             that were discarded or not sent.  For a MAC-layer
             protocol, this includes both Group and Functional
             addresses.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB -
                       ifHCOutMulticastPkts";
        }
        leaf out-discards {
          type uint32;
          config false;
          status deprecated;
          description
            "The number of outbound packets that were chosen to be
             discarded even though no errors had been detected to
             prevent their being transmitted.  One possible reason
             for discarding such a packet could be to free up buffer
             space.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifOutDiscards";
        }
        leaf out-errors {
          type uint32;
          config false;
          status deprecated;
          description
            "For packet-oriented interfaces, the number of outbound
             packets that could not be transmitted because of errors.
             For character-oriented or fixed-length interfaces, the
             number of outbound transmission units that could not be
             transmitted because of errors.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifOutErrors";
        }
      }
      container ipv4 {
        presence "true";
        config false;
        status deprecated;
        description
          "Interface-specific parameters for the IPv4 address family.";
        leaf forwarding {
          type boolean;
          config false;
          status deprecated;
          description
            "Indicates whether IPv4 packet forwarding is enabled or
             disabled on this interface.";
        }
        leaf mtu {
          type uint16 {
            range "68..65535";
          }
          units "octets";
          config false;
          status deprecated;
          description
            "The size, in octets, of the largest IPv4 packet that the
             interface will send and receive.";
          reference
            "RFC 791: Internet Protocol";
        }
        list address {
          key "ip";
          config false;
          min-elements 0;
          max-elements 4294967295;
          ordered-by user;
          status deprecated;
          description
            "The list of IPv4 addresses on the interface.";
          leaf ip {
            type string {
              pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
              pattern "[0-9\\.]*";
            }
            config false;
            status deprecated;
            description
              "The IPv4 address on the interface.";
          }
          choice subnet {
            config false;
            status deprecated;
            description
              "The subnet can be specified as a prefix length or,
               if the server supports non-contiguous netmasks, as
               a netmask.";
            case prefix-length {
              config false;
              status deprecated;
              leaf prefix-length {
                type uint8 {
                  range "0..32";
                }
                config false;
                status deprecated;
                description
                  "The length of the subnet prefix.";
              }
            }
            case netmask {
              config false;
              status deprecated;
            }
          }
          leaf origin {
            type enumeration {
              enum "other" {
                value 0;
                status current;
                description
                  "None of the following.";
              }
              enum "static" {
                value 1;
                status current;
                description
                  "Indicates that the address has been statically
                   configured -- for example, using the Network Configuration
                   Protocol (NETCONF) or a command line interface.";
              }
              enum "dhcp" {
                value 2;
                status current;
                description
                  "Indicates an address that has been assigned to this
                   system by a DHCP server.";
              }
              enum "link-layer" {
                value 3;
                status current;
                description
                  "Indicates an address created by IPv6 stateless
                   autoconfiguration that embeds a link-layer address in its
                   interface identifier.";
              }
              enum "random" {
                value 4;
                status current;
                description
                  "Indicates an address chosen by the system at
                   random, e.g., an IPv4 address within 169.254/16, a
                   temporary address as described in RFC 4941, or a
                   semantically opaque address as described in RFC 7217.";
                reference
                  "RFC 4941: Privacy Extensions for Stateless Address
                             Autoconfiguration in IPv6
                   RFC 7217: A Method for Generating Semantically Opaque
                             Interface Identifiers with IPv6 Stateless
                             Address Autoconfiguration (SLAAC)";
              }
            }
            config false;
            status deprecated;
            description
              "The origin of this address.";
          }
        }
        list neighbor {
          key "ip";
          config false;
          min-elements 0;
          max-elements 4294967295;
          ordered-by user;
          status deprecated;
          description
            "A list of mappings from IPv4 addresses to
             link-layer addresses.

             This list represents the ARP Cache.";
          reference
            "RFC 826: An Ethernet Address Resolution Protocol";
          leaf ip {
            type string {
              pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
              pattern "[0-9\\.]*";
            }
            config false;
            status deprecated;
            description
              "The IPv4 address of the neighbor node.";
          }
          leaf link-layer-address {
            type string {
              pattern "([0-9a-fA-F]{2}(:[0-9a-fA-F]{2})*)?";
            }
            config false;
            status deprecated;
            description
              "The link-layer address of the neighbor node.";
          }
          leaf origin {
            type enumeration {
              enum "other" {
                value 0;
                status current;
                description
                  "None of the following.";
              }
              enum "static" {
                value 1;
                status current;
                description
                  "Indicates that the mapping has been statically
                   configured -- for example, using NETCONF or a command line
                   interface.";
              }
              enum "dynamic" {
                value 2;
                status current;
                description
                  "Indicates that the mapping has been dynamically resolved
                   using, for example, IPv4 ARP or the IPv6 Neighbor
                   Discovery protocol.";
              }
            }
            config false;
            status deprecated;
            description
              "The origin of this neighbor entry.";
          }
        }
      }
      container ipv6 {
        presence "true";
        config false;
        status deprecated;
        description
          "Parameters for the IPv6 address family.";
        leaf forwarding {
          type boolean;
          default "false";
          config false;
          status deprecated;
          description
            "Indicates whether IPv6 packet forwarding is enabled or
             disabled on this interface.";
          reference
            "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                       Section 6.2.1, IsRouter";
        }
        leaf mtu {
          type uint32 {
            range "1280..4294967295";
          }
          units "octets";
          config false;
          status deprecated;
          description
            "The size, in octets, of the largest IPv6 packet that the
             interface will send and receive.";
          reference
            "RFC 8200: Internet Protocol, Version 6 (IPv6)
                       Specification
                       Section 5";
        }
        list address {
          key "ip";
          config false;
          min-elements 0;
          max-elements 4294967295;
          ordered-by user;
          status deprecated;
          description
            "The list of IPv6 addresses on the interface.";
          leaf ip {
            type string {
              pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
              pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
              pattern "[0-9a-fA-F:\\.]*";
            }
            config false;
            status deprecated;
            description
              "The IPv6 address on the interface.";
          }
          leaf prefix-length {
            type uint8 {
              range "0..128";
            }
            config false;
            mandatory true;
            status deprecated;
            description
              "The length of the subnet prefix.";
          }
          leaf origin {
            type enumeration {
              enum "other" {
                value 0;
                status current;
                description
                  "None of the following.";
              }
              enum "static" {
                value 1;
                status current;
                description
                  "Indicates that the address has been statically
                   configured -- for example, using the Network Configuration
                   Protocol (NETCONF) or a command line interface.";
              }
              enum "dhcp" {
                value 2;
                status current;
                description
                  "Indicates an address that has been assigned to this
                   system by a DHCP server.";
              }
              enum "link-layer" {
                value 3;
                status current;
                description
                  "Indicates an address created by IPv6 stateless
                   autoconfiguration that embeds a link-layer address in its
                   interface identifier.";
              }
              enum "random" {
                value 4;
                status current;
                description
                  "Indicates an address chosen by the system at
                   random, e.g., an IPv4 address within 169.254/16, a
                   temporary address as described in RFC 4941, or a
                   semantically opaque address as described in RFC 7217.";
                reference
                  "RFC 4941: Privacy Extensions for Stateless Address
                             Autoconfiguration in IPv6
                   RFC 7217: A Method for Generating Semantically Opaque
                             Interface Identifiers with IPv6 Stateless
                             Address Autoconfiguration (SLAAC)";
              }
            }
            config false;
            status deprecated;
            description
              "The origin of this address.";
          }
          leaf status {
            type enumeration {
              enum "preferred" {
                value 0;
                status current;
                description
                  "This is a valid address that can appear as the
                   destination or source address of a packet.";
              }
              enum "deprecated" {
                value 1;
                status current;
                description
                  "This is a valid but deprecated address that should
                   no longer be used as a source address in new
                   communications, but packets addressed to such an
                   address are processed as expected.";
              }
              enum "invalid" {
                value 2;
                status current;
                description
                  "This isn't a valid address, and it shouldn't appear
                   as the destination or source address of a packet.";
              }
              enum "inaccessible" {
                value 3;
                status current;
                description
                  "The address is not accessible because the interface
                   to which this address is assigned is not
                   operational.";
              }
              enum "unknown" {
                value 4;
                status current;
                description
                  "The status cannot be determined for some reason.";
              }
              enum "tentative" {
                value 5;
                status current;
                description
                  "The uniqueness of the address on the link is being
                   verified.  Addresses in this state should not be
                   used for general communication and should only be
                   used to determine the uniqueness of the address.";
              }
              enum "duplicate" {
                value 6;
                status current;
                description
                  "The address has been determined to be non-unique on
                   the link and so must not be used.";
              }
              enum "optimistic" {
                value 7;
                status current;
                description
                  "The address is available for use, subject to
                   restrictions, while its uniqueness on a link is
                   being verified.";
              }
            }
            config false;
            status deprecated;
            description
              "The status of an address.  Most of the states correspond
               to states from the IPv6 Stateless Address
               Autoconfiguration protocol.";
            reference
              "RFC 4293: Management Information Base for the
                         Internet Protocol (IP)
                         - IpAddressStatusTC
               RFC 4862: IPv6 Stateless Address Autoconfiguration";
          }
        }
        list neighbor {
          key "ip";
          config false;
          min-elements 0;
          max-elements 4294967295;
          ordered-by user;
          status deprecated;
          description
            "A list of mappings from IPv6 addresses to
             link-layer addresses.

             This list represents the Neighbor Cache.";
          reference
            "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)";
          leaf ip {
            type string {
              pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
              pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
              pattern "[0-9a-fA-F:\\.]*";
            }
            config false;
            status deprecated;
            description
              "The IPv6 address of the neighbor node.";
          }
          leaf link-layer-address {
            type string {
              pattern "([0-9a-fA-F]{2}(:[0-9a-fA-F]{2})*)?";
            }
            config false;
            status deprecated;
            description
              "The link-layer address of the neighbor node.";
          }
          leaf origin {
            type enumeration {
              enum "other" {
                value 0;
                status current;
                description
                  "None of the following.";
              }
              enum "static" {
                value 1;
                status current;
                description
                  "Indicates that the mapping has been statically
                   configured -- for example, using NETCONF or a command line
                   interface.";
              }
              enum "dynamic" {
                value 2;
                status current;
                description
                  "Indicates that the mapping has been dynamically resolved
                   using, for example, IPv4 ARP or the IPv6 Neighbor
                   Discovery protocol.";
              }
            }
            config false;
            status deprecated;
            description
              "The origin of this neighbor entry.";
          }
          leaf is-router {
            type empty;
            config false;
            status deprecated;
            description
              "Indicates that the neighbor node acts as a router.";
          }
          leaf state {
            type enumeration {
              enum "incomplete" {
                value 0;
                status current;
                description
                  "Address resolution is in progress, and the
                   link-layer address of the neighbor has not yet been
                   determined.";
              }
              enum "reachable" {
                value 1;
                status current;
                description
                  "Roughly speaking, the neighbor is known to have been
                   reachable recently (within tens of seconds ago).";
              }
              enum "stale" {
                value 2;
                status current;
                description
                  "The neighbor is no longer known to be reachable, but
                   until traffic is sent to the neighbor no attempt
                   should be made to verify its reachability.";
              }
              enum "delay" {
                value 3;
                status current;
                description
                  "The neighbor is no longer known to be reachable, and
                   traffic has recently been sent to the neighbor.
                   Rather than probe the neighbor immediately, however,
                   delay sending probes for a short while in order to
                   give upper-layer protocols a chance to provide
                   reachability confirmation.";
              }
              enum "probe" {
                value 4;
                status current;
                description
                  "The neighbor is no longer known to be reachable, and
                   unicast Neighbor Solicitation probes are being sent
                   to verify reachability.";
              }
            }
            config false;
            status deprecated;
            description
              "The Neighbor Unreachability Detection state of this
               entry.";
            reference
              "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                         Section 7.3.2";
          }
        }
      }
    }
  }
}

